<?php
require __DIR__.'/programaciones-common.php';
$id=prog_id($_GET,'id_plantilla');$session=prog_id($_GET,'sesion_editada');$template=prog_template($id);
if($session>(int)$template['num_sesiones'])prog_error('La sesión no pertenece a esta programación.');
$selected=app_rows('SELECT p.id_actividad,COALESCE(a.descripcion_actividad,p.actividad) AS descripcion_actividad FROM agenda_programacion_plantillas_actividades p LEFT JOIN agenda_programacion_actividades_piscina a ON a.id_actividad=p.id_actividad WHERE p.id_plantilla=? AND p.numero_sesion=? ORDER BY p.orden_actividad,p.id_prog','ii',[$id,$session]);
$chosen=[];foreach($selected as $activity)$chosen[(int)$activity['id_actividad']]=$activity;
$activities=app_rows('SELECT a.id_actividad,a.descripcion_actividad,o.nombre_objetivo,g.nombre_objetivo AS general FROM agenda_programacion_actividades_piscina a JOIN agenda_programacion_objetivos_piscina o ON o.id_objetivo=a.id_objetivo LEFT JOIN agenda_programacion_objetivos_piscina g ON g.id_objetivo=o.id_objetivo_g WHERE o.nivel=? AND o.id_objetivo_g<>0 ORDER BY o.id_objetivo_g,o.id_objetivo,a.id_actividad','i',[(int)$template['nivel']]);
$shown=[];foreach($activities as $activity)$shown[(int)$activity['id_actividad']]=true;
foreach($chosen as $key=>$activity){if(!isset($shown[$key])){$activity['general']='Actividad ya programada';$activity['nombre_objetivo']='';$activities[]=$activity;}}
$objectives=app_rows('SELECT o.id_objetivo,o.nombre_objetivo,g.nombre_objetivo AS general FROM agenda_programacion_objetivos_piscina o LEFT JOIN agenda_programacion_objetivos_piscina g ON g.id_objetivo=o.id_objetivo_g WHERE o.nivel=? AND o.id_objetivo_g<>0 ORDER BY o.id_objetivo_g,o.id_objetivo','i',[(int)$template['nivel']]);
$counts=[];foreach(app_rows('SELECT numero_sesion,COUNT(*) AS total FROM agenda_programacion_plantillas_actividades WHERE id_plantilla=? GROUP BY numero_sesion','i',[$id]) as $count)$counts[(int)$count['numero_sesion']]=(int)$count['total'];
prog_header('Sesión '.$session,(string)$template['descripcion'].' · '.prog_level($template['nivel']));
if(app_value($_GET,'done')==='saved'){?><p class="prog-notice" role="status">Sesión guardada.</p><?php }?>
<a class="prog-back" href="gestion_plantillas.php?id_plantilla=<?=$id?>">← Volver a la programación</a>
<form method="post" action="guarda_programacion_plantilla.php" id="prog-session-form"><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><input type="hidden" name="activity_list_submitted" value="1">
<div class="prog-activity-layout"><section class="prog-panel prog-activities"><div class="prog-section-title"><div><h2>Elige las actividades</h2><p class="prog-muted">Marca las actividades que se trabajarán durante esta sesión.</p></div><span class="prog-badge"><?=app_escape(prog_level($template['nivel']))?></span></div><label>Buscar actividad u objetivo<input type="search" id="prog-activity-search" placeholder="Escribe para encontrar una actividad"></label><div class="prog-activity-list">
<?php foreach($activities as $activity){$key=(int)$activity['id_actividad'];?><label class="prog-activity"><input type="checkbox" name="duallistbox_ActividadesProgramadas[]" value="<?=$key?>" data-activity data-description="<?=app_escape($activity['descripcion_actividad']?:'Actividad '.$key)?>" <?=isset($chosen[$key])?'checked':''?>><span><small><?=app_escape(trim(($activity['general']??'').' · '.($activity['nombre_objetivo']??''),' ·'))?></small><?=app_escape($activity['descripcion_actividad']?:'Actividad '.$key)?></span></label><?php }?>
<?php if(!$activities){?><p class="prog-empty">No hay actividades disponibles para este nivel. Puedes añadir la primera debajo.</p><?php }?></div></section>
<section class="prog-panel prog-activities"><div class="prog-section-title"><div><h2>Orden de la sesión</h2><p class="prog-muted">Usa las flechas para organizar las actividades.</p></div><span class="prog-badge"><span id="prog-selected-count"><?=count($chosen)?></span>&nbsp; actividades</span></div><ol class="prog-ordered" id="prog-selected"><?php foreach($chosen as $key=>$activity){?><li data-activity="<?=$key?>"><span><?=app_escape($activity['descripcion_actividad']?:'Actividad '.$key)?></span><input type="hidden" name="orden_actividades[]" value="<?=$key?>"><div class="prog-order-buttons"><button type="button" data-move="up" aria-label="Subir actividad">↑</button><button type="button" data-move="down" aria-label="Bajar actividad">↓</button></div></li><?php }?></ol><p class="prog-empty" id="prog-selected-empty" <?=count($chosen)?'hidden':''?>>Selecciona actividades para preparar esta sesión.</p></section></div>
<details class="prog-panel prog-copy"><summary>Copiar estas actividades en otras sesiones</summary><p class="prog-muted">Se copiarán cuando guardes. Las sesiones marcadas como preparadas ya tienen actividades.</p><div class="prog-copy-options"><?php for($n=1;$n<=(int)$template['num_sesiones'];$n++){if($n===$session)continue;?><label><input type="checkbox" name="sesiones_copiar[]" value="<?=$n?>">Sesión <?=$n?><?=isset($counts[$n])?' · Preparada':''?></label><?php }?></div><label>Actividades que ya existen en esas sesiones<select name="borrar"><option value="0">Conservarlas y añadir las nuevas</option><option value="1">Sustituirlas por las de esta sesión</option></select></label></details>
<details class="prog-panel prog-copy prog-new-activity"><summary>Crear una actividad para este nivel</summary><label>Objetivo<select name="objetivo_nueva"><option value="">Selecciona un objetivo</option><?php foreach($objectives as $objective){?><option value="<?=(int)$objective['id_objetivo']?>"><?=app_escape(($objective['general']?:'Objetivo').' · '.$objective['nombre_objetivo'])?></option><?php }?></select></label><label>Descripción<input type="text" name="actividad_nueva" maxlength="5000" placeholder="Explica el ejercicio que se realizará"></label><button class="prog-button secondary" name="nueva_act" value="1" type="submit">Guardar y añadir esta actividad</button></details>
<div class="prog-sticky-actions"><button class="prog-button" type="submit" name="volver" value="0">Guardar y volver</button><button class="prog-button secondary" type="submit" name="volver" value="1">Guardar y seguir editando</button><a class="prog-button secondary" href="gestion_plantillas.php?id_plantilla=<?=$id?>">Salir sin guardar</a><a class="prog-back" href="editar_objetivos_plantillas.php?id_plantilla=<?=$id?>&amp;sesion_editada=<?=$session?>">Gestionar objetivos y actividades</a></div></form>
<?php prog_footer(); ?>